<script lang="ts">
  import { page } from '$app/state';
  import { useDemo } from '#lib/demo.svelte';
  import { phaseNames, productById, projects } from '#lib/data';
  import { money } from '#lib/pricing';
  import DemoVideo from '#lib/components/DemoVideo.svelte';
  import Reviews from '#lib/components/Reviews.svelte';
  const demo = useDemo();
  const order = $derived(demo.state.orders.find((o) => o.id === page.params.id));
  const project = $derived(order ? projects.find((p) => order.lines.some((l) => l.projectId === p.id)) ?? projects.find((p) => order.lines.some((l) => p.phases.some((s) => s.productId === l.productId))) : undefined);
  const stages = [['Confirmado','Confirmed'],['Preparando','Preparing'],['En camino','On the way'],['Entregado','Delivered']];
  const contacts = [['Confirmación y resumen','Confirmation and overview'],['Acceso al tutorial','Tutorial access'],['Orden de aplicación','Application order'],['Seguridad y preparación','Safety and preparation'],['Siguiente fase','Next phase'],['Solicitud de valoración','Review request'],['Comparte tus fotos','Share your photos'],['Tu próximo proyecto','Your next project']];
</script>
{#if order}<section class="section cream"><div class="container"><div class="eyebrow">✓ {demo.t('PEDIDO FICTICIO CONFIRMADO','FICTIONAL ORDER CONFIRMED')} · {order.id}</div><h1>{demo.t('Ya tienes tu proyecto preparado.','Your project is ready.')}</h1><p class="demo-note">{demo.t('Este pedido es ficticio y local. No se ha cobrado ni se enviará nada.','This order is fictional and local. Nothing has been charged or will be shipped.')}</p><div class="detail-hero"><div>{#if project}<div class="card card-body"><h2>{project.title[demo.state.language]}</h2><div class="grid cols-4">{#each project.phases as p,i}<div class="callout" style="padding:12px;margin:0"><strong>{i+1} · {phaseNames[p.phase][demo.state.language]}</strong><p class="muted">{productById(p.productId).name}<br/>{p.drying} min · demo</p></div>{/each}</div><div class="row" style="margin-top:20px"><a class="button" href={`/proyectos/${project.id}#pasos`}>{demo.t('Ver tutorial completo','View full tutorial')}</a><a class="button secondary" href={`/guia?project=${project.id}`}>{demo.t('Guía imprimible / PDF','Printable guide / PDF')}</a></div></div>{/if}<div class="callout"><h3>{demo.t('Seguridad y preparación','Safety and preparation')}</h3><p>{demo.t('Consulta instrucciones y fichas aprobadas antes de un proyecto real. Los tiempos de la demo son ficticios.','Consult approved instructions and sheets before a real project. Demo timing is fictional.')}</p><a href="/guia?type=seguridad">{demo.t('Documento de muestra →','Sample document →')}</a></div></div><div><div class="card card-body" id="resumen"><h2>{demo.t('Resumen del pedido','Order summary')}</h2>{#each order.lines as line}<p>{line.quantity} × {line.kind === 'kit' ? `Kit · ${projects.find((p) => p.id === line.projectId)?.title[demo.state.language]}` : productById(line.productId!).name}</p>{/each}<dl class="totals"><div><dt>Subtotal</dt><dd>{money(order.subtotal,demo.state.language)}</dd></div><div><dt>{demo.t('Descuento','Discount')}</dt><dd>−{money(order.discount,demo.state.language)}</dd></div><div><dt>{demo.t('Envío ficticio','Fictional shipping')}</dt><dd>{money(order.shipping,demo.state.language)}</dd></div><div class="grand"><dt>Total</dt><dd>{money(order.total,demo.state.language)}</dd></div></dl><p class="muted">{demo.t('Entrega ficticia estimada','Estimated fictional delivery')}: {new Date(new Date(order.created).getTime()+ (order.market === 'EU' ? 5 : 10)*86400000).toLocaleDateString(demo.state.language)}</p><a href="#seguimiento">{demo.t('Ver seguimiento simulado →','View simulated tracking →')}</a></div><div style="margin-top:20px"><DemoVideo title={demo.t('Resumen','Overview')}/></div><div class="callout"><h3>{demo.t('Recordatorios simulados','Simulated reminders')}</h3>{#each ['Email','SMS / WhatsApp'] as channel}<label class="check" style="margin:15px 0"><input type="checkbox" checked={order.reminders.includes(channel)} onchange={(e) => { if (e.currentTarget.checked) order.reminders.push(channel); else order.reminders = order.reminders.filter((c) => c !== channel); }}/>{channel} · demo</label>{/each}<p class="muted">{demo.t('Preferencias locales; no se envían mensajes.','Local preferences; no messages sent.')}</p></div></div></div></div></section><section class="section" id="seguimiento"><div class="container"><h2>{demo.t('Seguimiento simulado','Simulated tracking')}</h2><div class="phase-tabs">{#each stages as stage,i}<button class:selected={order.status === i} onclick={() => order.status = i}><small>0{i+1}</small>{demo.t(stage[0],stage[1])}</button>{/each}</div><p role="status">{demo.t('Estado ficticio','Fictional status')}: {demo.t(stages[order.status][0],stages[order.status][1])}</p><button class="secondary" disabled={order.status === 3} onclick={() => order.status = Math.min(3,order.status+1)}>{demo.t('Avanzar entrega simulada','Advance simulated delivery')}</button><h2 style="margin-top:45px">{demo.t('Secuencia poscompra · 8 contactos demo','Post-purchase sequence · 8 demo contacts')}</h2><div class="timeline">{#each contacts as c,i}<article><span class="step-number">{i+1}</span><div class="row between"><div><h3>{demo.t(c[0],c[1])}</h3><p class="muted">{demo.t('Vista previa local. Sin envío de email o SMS.','Local preview. No email or SMS sent.')}</p></div><a class="button secondary" href={i === 0 ? '#resumen' : i === 3 ? '/guia?type=seguridad' : i === 5 || i === 6 ? '#valoraciones' : i === 7 ? '/proyectos' : project ? `/proyectos/${project.id}#${i === 4 ? 'prepara' : 'pasos'}` : '/como-se-hace'}>{demo.t('Abrir contenido','Open content')}</a></div></article>{/each}</div><div style="margin-top:40px"><Reviews target={project?.id ?? order.id}/></div></div></section>{:else}<section class="section"><div class="container"><h1>{demo.t('Pedido local no encontrado','Local order not found')}</h1><p>{demo.t('Los pedidos solo están disponibles en el navegador donde se crearon.','Orders are only available in the browser where they were created.')}</p><a class="button" href="/pedidos">{demo.t('Ver mis pedidos','View my orders')}</a></div></section>{/if}
